using Microsoft.Data.Sqlite;
namespace AgentRecorder.Infrastructure;

internal static class SqliteSchemaV48
{
    internal const string Name="schema_v48_bounded_deletion_batches";
    internal static readonly (string Type,string Name,string Sql)[] Objects={
        ("table","ordinary_deletion_batches","CREATE TABLE ordinary_deletion_batches (\n batch_id TEXT NOT NULL COLLATE BINARY CHECK(length(batch_id)=32 AND instr(batch_id,char(0))=0 AND batch_id NOT GLOB '*[^0-9a-f]*') PRIMARY KEY,\n owner_sid TEXT NOT NULL COLLATE BINARY CHECK(length(owner_sid) BETWEEN 1 AND 256 AND instr(owner_sid,char(0))=0),\n owner_session TEXT NOT NULL COLLATE BINARY CHECK(length(owner_session) BETWEEN 1 AND 256 AND instr(owner_session,char(0))=0),\n videos_root TEXT NOT NULL COLLATE BINARY CHECK(length(videos_root) BETWEEN 1 AND 1024 AND instr(videos_root,char(0))=0),\n host_id TEXT NOT NULL COLLATE BINARY CHECK(length(host_id)=32 AND instr(host_id,char(0))=0 AND host_id NOT GLOB '*[^0-9a-f]*'),\n key_digest TEXT NOT NULL COLLATE BINARY CHECK(length(key_digest)=64 AND instr(key_digest,char(0))=0 AND key_digest NOT GLOB '*[^0-9a-f]*'),\n request_digest TEXT NOT NULL COLLATE BINARY CHECK(length(request_digest)=64 AND instr(request_digest,char(0))=0 AND request_digest NOT GLOB '*[^0-9a-f]*'),\n binding_digest TEXT NOT NULL COLLATE BINARY CHECK(length(binding_digest)=64 AND instr(binding_digest,char(0))=0 AND binding_digest NOT GLOB '*[^0-9a-f]*'),\n item_count INTEGER NOT NULL CHECK(item_count BETWEEN 1 AND 5),\n created_ticks INTEGER NOT NULL CHECK(created_ticks BETWEEN 0 AND 3155378969999999999),\n expires_ticks INTEGER NOT NULL CHECK(expires_ticks=created_ticks+6000000000),\n phase TEXT NOT NULL CHECK(phase IN ('active','finished')),\n stop_reason TEXT NULL CHECK(length(stop_reason) BETWEEN 1 AND 128 AND instr(stop_reason,char(0))=0),\n updated_ticks INTEGER NOT NULL CHECK(updated_ticks BETWEEN created_ticks AND 3155378975999999999),\n CHECK((phase='active' AND stop_reason IS NULL) OR (phase='finished' AND stop_reason IS NOT NULL))\n) STRICT"),
        ("table","ordinary_deletion_batch_items","CREATE TABLE ordinary_deletion_batch_items (\n batch_id TEXT NOT NULL COLLATE BINARY CHECK(length(batch_id)=32 AND instr(batch_id,char(0))=0 AND batch_id NOT GLOB '*[^0-9a-f]*') REFERENCES ordinary_deletion_batches(batch_id),\n ordinal INTEGER NOT NULL CHECK(ordinal BETWEEN 0 AND 4),\n recording_id TEXT NOT NULL COLLATE BINARY CHECK(length(recording_id) BETWEEN 1 AND 200 AND instr(recording_id,char(0))=0),\n child_request_id TEXT NOT NULL COLLATE BINARY CHECK(length(child_request_id)=32 AND instr(child_request_id,char(0))=0 AND child_request_id NOT GLOB '*[^0-9a-f]*') UNIQUE,\n child_key TEXT NOT NULL COLLATE BINARY CHECK(length(child_key)=32 AND instr(child_key,char(0))=0 AND child_key NOT GLOB '*[^0-9a-f]*') UNIQUE,\n phase TEXT NOT NULL CHECK(phase IN ('not_requested','dispatch_reserved','finished')),\n outcome TEXT NULL CHECK(outcome IN ('accepted','non_success')),\n reason TEXT NULL CHECK(length(reason) BETWEEN 1 AND 128 AND instr(reason,char(0))=0),\n resources_retired INTEGER NULL CHECK(resources_retired IN (0,1)),\n PRIMARY KEY(batch_id,ordinal),\n UNIQUE(batch_id,recording_id),\n CHECK((phase IN ('not_requested','dispatch_reserved') AND outcome IS NULL AND reason IS NULL AND resources_retired IS NULL) OR (phase='finished' AND outcome IS NOT NULL AND reason IS NOT NULL AND resources_retired IS NOT NULL))\n) STRICT"),
        ("index","idx_deletion_batch_key","CREATE UNIQUE INDEX idx_deletion_batch_key ON ordinary_deletion_batches(owner_sid COLLATE BINARY,owner_session COLLATE BINARY,key_digest COLLATE BINARY)"),
        ("trigger","deletion_batch_no_delete","CREATE TRIGGER deletion_batch_no_delete BEFORE DELETE ON ordinary_deletion_batches BEGIN SELECT RAISE(ABORT,'batch deletion evidence is retained'); END"),
        ("trigger","deletion_batch_item_no_delete","CREATE TRIGGER deletion_batch_item_no_delete BEFORE DELETE ON ordinary_deletion_batch_items BEGIN SELECT RAISE(ABORT,'batch deletion evidence is retained'); END"),
        ("trigger","deletion_batch_transition","CREATE TRIGGER deletion_batch_transition BEFORE UPDATE ON ordinary_deletion_batches WHEN NEW.batch_id IS NOT OLD.batch_id OR NEW.owner_sid IS NOT OLD.owner_sid OR NEW.owner_session IS NOT OLD.owner_session OR NEW.videos_root IS NOT OLD.videos_root OR NEW.host_id IS NOT OLD.host_id OR NEW.key_digest IS NOT OLD.key_digest OR NEW.request_digest IS NOT OLD.request_digest OR NEW.binding_digest IS NOT OLD.binding_digest OR NEW.item_count IS NOT OLD.item_count OR NEW.created_ticks IS NOT OLD.created_ticks OR NEW.expires_ticks IS NOT OLD.expires_ticks OR NOT (OLD.phase='active' AND NEW.phase='finished') BEGIN SELECT RAISE(ABORT,'invalid batch transition'); END"),
        ("trigger","deletion_batch_item_transition","CREATE TRIGGER deletion_batch_item_transition BEFORE UPDATE ON ordinary_deletion_batch_items WHEN NEW.batch_id IS NOT OLD.batch_id OR NEW.ordinal IS NOT OLD.ordinal OR NEW.recording_id IS NOT OLD.recording_id OR NEW.child_request_id IS NOT OLD.child_request_id OR NEW.child_key IS NOT OLD.child_key OR NOT ((OLD.phase='not_requested' AND NEW.phase='dispatch_reserved') OR (OLD.phase='dispatch_reserved' AND NEW.phase='finished')) OR NOT EXISTS(SELECT 1 FROM ordinary_deletion_batches b WHERE b.batch_id=OLD.batch_id AND b.phase='active') OR EXISTS(SELECT 1 FROM ordinary_deletion_batch_items p WHERE p.batch_id=OLD.batch_id AND p.ordinal<OLD.ordinal AND (p.phase<>'finished' OR p.outcome<>'accepted' OR p.resources_retired<>1)) BEGIN SELECT RAISE(ABORT,'invalid batch item transition'); END")
    };
    internal static readonly string Definition=string.Join(";\n",Objects.Select(x=>x.Sql))+";";
    internal const string Checksum="818fc70ecaedcd73d2fdaf1884ac94e33d24f5eed62dfc455ce543c932d26f6b";
    internal static IReadOnlyList<SqliteMigrationDefinition> Migrations {get;}=new[]{new SqliteMigrationDefinition(48,Name,Definition,Checksum)};
    internal static void Validate(SqliteConnection c,SqliteTransaction? t)
    {
        if(SqliteSchemaV1.ComputeChecksum(Definition)!=Checksum)throw new InvalidDataException("Batch schema checksum differs.");
        using var cmd=c.CreateCommand();cmd.Transaction=t;
        foreach(var o in Objects){cmd.CommandText="SELECT sql FROM sqlite_master WHERE type=$type AND name=$name;";cmd.Parameters.AddWithValue("$type",o.Type);cmd.Parameters.AddWithValue("$name",o.Name);
            if(cmd.ExecuteScalar() is not string sql||SqliteSchemaV1.CanonicalizeDefinition(sql.TrimEnd(';'))!=SqliteSchemaV1.CanonicalizeDefinition(o.Sql))throw new InvalidDataException("Batch schema differs.");cmd.Parameters.Clear();}
        cmd.CommandText="SELECT name,definition_checksum FROM schema_migrations WHERE version=48;";using var r=cmd.ExecuteReader();
        if(!r.Read()||r.GetValue(0) is not string name||name!=Name||r.GetValue(1) is not string hash||hash!=Checksum||r.Read())throw new InvalidDataException("Batch receipt differs.");
    }
}
